package com.vynedam.stockai.service;
import com.vynedam.stockai.dto.AuthDtos.*; import com.vynedam.stockai.repository.UserRepository; import com.vynedam.stockai.security.JwtService; import org.junit.jupiter.api.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class AuthServiceTests { @Test void storesHashAndIssuesSignedToken(){var repo=mock(UserRepository.class);when(repo.existsByEmailIgnoreCase("admin@example.com")).thenReturn(false);when(repo.save(any())).thenAnswer(x->{var u=x.getArgument(0,com.vynedam.stockai.model.User.class);u.id="u1";return u;});var service=new AuthService(repo,new BCryptPasswordEncoder(),new JwtService("12345678901234567890123456789012",3600));var response=service.register(new RegisterRequest("Admin","ADMIN@example.com","correct-horse-battery-staple",null));assertEquals("admin@example.com",response.user().email());assertNotEquals("correct-horse-battery-staple",response.accessToken());verify(repo).save(argThat(u->u.passwordHash.startsWith("$2")));}}
